import { env } from 'cloudflare:workers';
import { getChatGPTUser } from '../../chatgpt-auth';
function db(){ if("'!env.DB)throw new Error('"'Storage unavailable'); return env.DB; }
export async function GET(){ if("'!await getChatGPTUser())return Response.json({error:'"'Sign in required'},{status:401});try {return Response.json({notes:(await db().prepare('SELECT id, content, updated FROM visit_notes').all()).results});}catch{return Response.json({error:'Saved visit records are temporarily unavailable.'},{status:503});}}
export async function POST(request:Request){if("'!await getChatGPTUser())return Response.json({error:'"'Sign in required'},{status:401});if(request.headers.get('origin')"'!==new URL(request.url).origin)return Response.json({error:'"'Invalid request origin'},{status:403});try{const {id,content}=await request.json();if(typeof id"'!=='"'string'||typeof content"'!=='"'string'||id.length>100||content.length>20000)return Response.json({error:'Invalid note'},{status:400});const updated=new Date().toISOString();await db().prepare('INSERT INTO visit_notes (id,content,updated) VALUES (?,?,?) ON CONFLICT(id) DO UPDATE SET content=excluded.content, updated=excluded.updated').bind(id,content,updated).run();return Response.json({updated});}catch{return Response.json({error:'Could not save. Your entered text remains here; please retry.'},{status:503});}}
EOF
cat > app/page.tsx <<'EOF'
'use client';
import {useEffect,useState} from 'react';
import data from './data.json';
import {ShieldCheck,FileText,Search,CalendarDays,Receipt,Wallet,Tablet,ClipboardList,AlertCircle,Printer,Download,ChevronRight, X,Check} from 'lucide-react';
const D:any=data;const money=(n:number)=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(n/100);const month=(id:string)=>new Date(id+'-22T12:00:00').toLocaleDateString('en-US',{month:'short',year:'numeric'});const tabs=['AT&T Store Visit','Monthly timeline','Charges & credits','Payments & balances','Lines & devices','Insurance & deductibles','Disputed items','Unresolved questions','Evidence library'];const icons=[ClipboardList,CalendarDays,Receipt,Wallet,Tablet,ShieldCheck,AlertCircle,Search,FileText];
export default function Audit(){const[tab,setTab]=useState(tabs[0]);const[m,setM]=useState('All');const[line,setLine]=useState('All');const[cat,setCat]=useState('All');const[q,setQ]=useState('');const[evidence,setEvidence]=useState<any>(null);const[notes,setNotes]=useState<any>({});const[message,setMessage]=useState('');const[loaded,setLoaded]=useState(false);const[busy,setBusy]=useState('');
useEffect(()=>{fetch('/api/notes').then(async r=>{if("'!r.ok)throw Error();let x=await r.json();let n:any={};x.notes.forEach((a:any)=>n[a.id]=a.content);setNotes(n);setLoaded(true)}).catch(()=>setMessage('"'Saved visit records could not be loaded. You can enter responses and retry saving.'));},[]);
const bills=D.bills.filter((b:any)=>m==='All'||b.id===m);const allRows=D.rows.filter((r:any)=>(m==='All'||r.bill===m)&&(line==='All'||r.line===line)&&(cat==='All'||r.category===cat)&&("'!q||JSON.stringify(r).toLowerCase().includes(q.toLowerCase())));const lines=Array.from(new Set(D.rows.map((r:any)=>r.line))).sort() as string[];const categories=Array.from(new Set(D.rows.map((r:any)=>r.category))).sort() as string[];
const cite=(bill:string,page:number)=>{let b=D.bills.find((x:any)=>x.id===bill);return <button className="citation" onClick={()=>setEvidence({bill,page})}>{month(bill)} · p. {page}<FileText size={13}/></button>};
const references=(rs:any[])=>Array.from(new Set(rs.map(r=>r.bill+'"'|'+r.page))).map((v:any)=>{let[b,p]=v.split('|');return <span key={v}>{cite(b,+p)} </span>});const sum=(rs:any[])=>rs.reduce((s,r)=>s+r.amount,0);const tablet=D.rows.filter((r:any)=>r.line==='817-879-6788');const deduct=D.rows.filter((r:any)=>r.category==='Replacement deductible');const nonreturn=D.rows.filter((r:any)=>r.category==='Device non-return fee');const courtesy=D.rows.filter((r:any)=>r.category==='Courtesy credits');const late=D.rows.filter((r:any)=>r.category==='Late fees');const restoral=D.rows.filter((r:any)=>r.category==='Restoral fees');const admin=D.rows.filter((r:any)=>r.category==='Administrative fee');
const questions=[{id:'tablet',title:'Questioned tablet · 817-879-6788',exposure:money(sum(tablet)),type:'Calculated billed exposure',question:'Who requested the March 19, 2026 addition, through which channel, and under what authorization? Provide the order, consent record, IMEI, ICCID/eSIM, device shipment or pickup record, and account notes. Was this intended as a replacement or an additional line? Explain why existing tablet 682-359-3466 continued to be billed; identify which tablet/device used each line. If the addition was not authorized, specify the reversal of plan charges, fees and applicable taxes, and the effective cancellation date.',detail:'March bill p. 11 states “Mar 19: Added”, "'$2.67 partial plan charge, $35 activation and matching −$35 activation credit. Recurring plan is $20.00. Presence and usage do not establish consent. Seven statement line totals sum to $175.06; March includes partial-period activity.'"',refs:tablet},
{id:'claims',title:'Two replacements · claim matching',exposure:money(sum(deduct)),type:'Verified billed charges / user-reported legitimacy',question:'Provide separate claim IDs, loss dates, covered devices and IMEIs, shipment details, replacement fulfillment records and deductible authorizations for January 27 and March 19. Confirm which of the two user-recognized legitimate replacements each charge represents. Do not combine the two claim records.',detail:'Two Standard Replacement Deductible entries of "'$275.00 each are printed. User identifies two legitimate replacements; the statements alone do not establish which physical devices they correspond to.'"',refs:deduct},
{id:'third',title:'Third disputed deductible',exposure:'Amount unresolved',type:'User-reported / unresolved',question:'Identify any third replacement deductible in the full account and insurer ledger. Supply date, amount, claim ID, device/IMEI and authorization. If none exists, explain what charge was described as a third deductible and reconcile it to the two "'$275 entries and the distinct $285 non-return fee.'"',detail:'No third charge labeled Standard Replacement Deductible was located in the 11 supplied monthly statements. Do not insert an assumed third "'$275 charge.'"',refs:deduct},
{id:'return',title:'Protect Advantage · non-return fee',exposure:'"'$285.00'"',type:'Verified fee; entitlement unresolved',question:'For the May 18 "'$285 Device Non-Return Fee, identify the associated claim and original device/IMEI, return deadline, notices, return label, tracking, carrier acceptance and warehouse receipt. Explain the basis of the fee and whether a return was received or credited. If reversed, itemize the fee and tax corrections.'"',detail:'This is a device non-return fee, separately labeled from the two replacement deductibles. No return or non-return conclusion is established by the billing entry alone. Tax exposure is not added without AT&T attribution.',refs:nonreturn},
{id:'credits',title:'Courtesy credits · allocation and posting',exposure:money(-sum(courtesy)),type:'Verified credits already printed',question:'Explain the purpose and disputed items covered by the March 19 "'$40.00 and September 8 $121.70 courtesy credits. Provide the adjustment IDs and allocation. Were they discretionary credits or reversals? Show the complete credit ledger and confirm that neither is being counted twice.'"',detail:'Printed credits total "'$161.70. They are not deducted from disputed exposure without a documented allocation.'"',refs:courtesy},
{id:'promise',title:'October 5 · promised "'$120 credit'"',exposure:'"'$120.00 pending'"',type:'User-reported promise',question:'Confirm the "'$120 credit promised on October 5, 2026: representative, interaction/case ID, reason, exact amount, posting date and whether it is additional to the September $121.70. Provide written confirmation and an updated balance after it actually posts.'"',detail:'Source: user report in this conversation, October 5, 2026. No supplied bill verifies posting. Latest statement balance is a September snapshot, not a live balance.',refs:[]},
{id:'fees',title:'Late and restoral fees',exposure:money(sum(late)+sum(restoral)),type:'Calculated fee exposure',question:'For each late fee and the July 22 "'$35 restoral fee, provide the due date, delinquent amount, assessed rate, suspension/restoration records, and payment posting times. Which fees resulted from amounts later corrected? Itemize any fee and related tax relief rather than assuming all fees should be refunded.'"',detail:"'`Late fees total ${money(sum(late))}; restoral fee totals ${money(sum(restoral))}. Associated account taxes and surcharges remain separately itemized in the ledger. A cover-page warning about a possible fee is not a charged fee.`,refs:[...late,...restoral]},
{id:'"'admin',title:'Administrative fees and September plan prices',exposure:'Review per line',type:'Verified fees / unresolved explanation',question:'Explain and supply notices for administrative fee changes from "'$1.99 to $2.49 and later $3.49. Confirm the effective dates for each line. Explain September phone plan charges of $75 versus August $70 on 682-371-8439 and 817-964-2604, including contractual basis and $5 price-adjustment history.'"',detail:'November p. 11 announces a "'$0.50 administrative fee increase effective December 1, 2025. Per-line fee amounts are preserved in the ledger. Compare August and September phone pages before assigning any refund entitlement.'"',refs:admin},
{id:'oldtablet',title:'Existing tablet · removal and continuity',exposure:'Avoid overlapping recovery',type:'Verified presence / unresolved account history',question:'Explain why 682-359-3466 is present through August but absent from the September statement. Supply cancellation date, requester, order and final proration/credit. Explain how its device relates to 817-879-6788, and provide a current inventory of all active lines and associated devices.',detail:'The two tablet numbers are distinct statement entries. September lists 817-879-6788; the existing 682-359-3466 is absent. Absence does not establish the reason or authorization for removal.',refs:D.rows.filter((r:any)=>r.line==='682-359-3466'&&['2025-11','2026-08'].includes(r.bill)).concat(D.rows.filter((r:any)=>r.line==='817-879-6788'&&r.bill==='2026-09'))}];
async function save(id:string){setBusy(id);try{let r=await fetch('/api/notes',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id,content:notes[id]||''})});if("'!r.ok)throw Error((await r.json()).error);setMessage('"'Response saved · '+new Date().toLocaleTimeString());setLoaded(true)}catch(e:any){setMessage(e.message||'Could not save. Please retry; your text is retained.')}setBusy('')}
function exportNotes(){const blob=new Blob([JSON.stringify({asOf:D.asOf,notes},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='GMRI-ATT-store-visit-record.json';a.click();URL.revokeObjectURL(a.href)}
const table=(rs:any[])=><div className=\"tablewrap\"><table><thead><tr><th>Bill / line</th><th>Printed charge or credit</th><th>Category</th><th className=\"number\">Amount</th><th>Evidence</th></tr></thead><tbody>{rs.map((r:any,i:number)=><tr key={i} className={r.line==='817-879-6788'?'questioned':''}><td><strong>{month(r.bill)}</strong><small>{r.line}</small></td><td><details><summary>{r.name}</summary><pre>{r.raw}</pre><small>Verified statement fact · {r.section||'Account activity'}</small></details></td><td>{r.category}</td><td className={'number '+(r.amount<0?'credit':'')}>{r.printed}</td><td>{cite(r.bill,r.page)}</td></tr>)}</tbody></table>{"'!rs.length&&<p className="empty">No entries match these filters.</p>}</div>;
return <div className="shell"><aside><div className="brand"><img src="/gmri-logo.jpeg" alt="GrizzlyMedicine Research Institute crest"/><div>GRIZZLYMEDICINE<small>RESEARCH INSTITUTE</small></div></div><div className="case">ACCOUNT REVIEW<span>AT&T billing audit</span><small>Nov 2025 — Sep 2026</small></div><nav>{tabs.map((t,i)=>{const Icon=icons[i];return <button key={t} className={tab===t?'"'active':''} onClick={()=>setTab(t)}><Icon size={18}/>{t}</button>})}</nav><div className=\"asidebottom\"><ShieldCheck size={19}/><span>Evidence before conclusions<small>Private audit workspace</small></span></div></aside><main><header><div><div className=\"eyebrow\">GMRI / FORENSIC BILLING REVIEW</div><h1>{tab}</h1></div><div className=\"actions\"><button onClick={()=>window.print()}><Printer size={16}/>Print</button><button onClick={exportNotes}><Download size={16}/>Export visit record</button></div></header><div className=\"statusline\"><span>11 statements</span><span>620 itemized entries</span><span>Snapshot · Oct 5, 2026</span><span>Latest supplied bill · Sep 22</span></div><div className=\"legend\"><span className=\"badge verified\">Verified statement fact</span><span className=\"badge reported\">User-reported</span><span className=\"badge calculated\">Calculation</span><span className=\"badge unresolved\">Unresolved</span></div>
<div className=\"filters\"><label>Bill month<select value={m} onChange={e=>setM(e.target.value)}><option>All</option>{D.bills.map((b:any)=><option key={b.id} value={b.id}>{month(b.id)}</option>)}</select></label><label>Wireless line<select value={line} onChange={e=>setLine(e.target.value)}><option>All</option>{lines.map(x=><option key={x}>{x}</option>)}</select></label><label>Charge category<select value={cat} onChange={e=>setCat(e.target.value)}><option>All</option>{categories.map(x=><option key={x}>{x}</option>)}</select></label><label className=\"search\">Find an entry<div><Search size={17}/><input value={q} onChange={e=>setQ(e.target.value)} placeholder=\"Charge, date, line or amount\"/></div></label><button onClick={()=>{setM('All');setLine('All');setCat('All');setQ('')}}>Reset</button></div>
{tab==='AT&T Store Visit'&&<><div className=\"visitintro\"><div><div className=\"eyebrow\">BRING THE RECORD. GET THE ANSWERS.</div><h2>Every correction needs a paper trail.</h2><p>Ask for the order, claim or adjustment record behind each answer. Record the representative’s explanation, exact correction and posting commitment below.</p></div><div className=\"snapshot\"><small>Latest statement total due</small><strong>"'$746.06</strong>{cite('"'2026-09',1)}<small>September snapshot · not a live balance</small></div></div><div className=\"note\"><AlertCircle size={19}/><span>Questioned amounts are review exposure, not proven overbilling. Do not add legitimate deductibles, posted credits and a promised credit into a single refund figure. No authorization or wrongdoing is inferred.</span></div><section className=\"visitmeta\"><h3>Visit record</h3><label>Representative · store · visit date · case number<textarea value={notes.visit||''} onChange={e=>setNotes({...notes,visit:e.target.value})} placeholder=\"Name, store location, date/time, case or escalation number\"/></label><button className=\"primary\" onClick={()=>save('visit')}>Save visit details</button><p role=\"status\">{message|| (loaded?'Saved responses loaded.':'Loading saved responses…')}</p></section><div className=\"questions\">{questions.filter(a=>{if(m==='All'&&line==='All'&&cat==='All'&&"'!q)return true;if(!a.refs.length)return true;return a.refs.some((r:any)=>allRows.includes(r))||a.title.toLowerCase().includes(q.toLowerCase())&&!!q}).map((a,i)=><article key={a.id}><div className="questiontop"><span className="ordinal">{String(i+1).padStart(2,'"'0')}</span><div><h3>{a.title}</h3><span className=\"badge unresolved\">{a.type}</span></div><div className=\"exposure\"><small>Review exposure</small><strong>{a.exposure}</strong></div></div><p className=\"questiontext\">{a.question}</p><details><summary>Supporting evidence and scope</summary><p>{a.detail}</p><div>{references(a.refs)}</div></details><label>Representative’s explanation · credits/corrections promised · posting date<textarea value={notes[a.id]||''} onChange={e=>setNotes({...notes,[a.id]:e.target.value})} placeholder=\"Record exact explanation, claim/order ID, amount, adjustment ID, promised posting date and follow-up owner.\"/></label><button className=\"primary\" disabled={busy===a.id} onClick={()=>save(a.id)}>{busy===a.id?'Saving…':'Save response'}</button></article>)}</div></>}
{tab==='Monthly timeline'&&<><h2>Current charges and carried balances</h2><p className=\"muted\">Bill issue month is distinct from the forward monthly service period. Total due includes carried balances; summing totals due would double-count them.</p><div className=\"timeline\">{bills.map((b:any)=>{let rs=allRows.filter((r:any)=>r.bill===b.id);return <article key={b.id}><div className=\"monthhead\"><h3>{month(b.id)}</h3>{cite(b.id,1)}</div><div className=\"bar\" style={{width:Math.max(12,b.services/600)+'%'}}/><div className=\"monthstats\"><span>Current services<strong>{money(b.services)}</strong></span><span>Total due<strong>{money(b.total)}</strong></span><span>Carried balance<strong>{money(b.carry)}</strong></span></div><details><summary>{rs.length} matching entries · drill down</summary>{table(rs)}</details></article>})}</div></>}
{tab==='Charges & credits'&&<><div className=\"sectionheading\"><h2>Itemized ledger</h2><span>{allRows.length} matching entries · signed sum {money(sum(allRows))}</span></div><p className=\"muted\">Payments and courtesy balance adjustments remain separate categories; the signed sum depends on selected categories and is not a refund calculation.</p>{table(allRows)}</>}
{tab==='Payments & balances'&&<><h2>Statement balance reconciliation</h2><p className=\"muted\">Whole-account balances below honor the month filter. Line, category and search filters apply to the transaction ledger, not the account balance.</p><div className=\"tablewrap\"><table><thead><tr><th>Bill</th><th>Last bill</th><th>Payments</th><th>Adjustments</th><th>Carry</th><th>New services</th><th>Total due</th><th>Check</th></tr></thead><tbody>{bills.map((b:any)=><tr key={b.id}><td>{cite(b.id,1)}</td>{['last','payments','adjustments','carry','services','total'].map(k=><td key={k} className=\"number\">{money(b[k])}</td>)}<td><span className=\"badge verified\">{b.last+b.payments+b.adjustments+b.services===b.total?'Reconciles':'Review'}</span></td></tr>)}</tbody></table></div><p className=\"muted\">Calculation: last bill + signed payments + signed adjustments + new services = total due. November is the opening supplied statement; no prior-bill balance is shown.</p>{table(allRows.filter((r:any)=>['Payments','Courtesy credits','Late fees','Restoral fees','Account fees / taxes'].includes(r.category)))}</>}
{tab==='Lines & devices'&&<><h2>Distinct numbers. Distinct billing histories.</h2><p className=\"muted\">Statements identify line types and subscriber labels. They do not supply reliable physical-device identifiers or prove who authorized a line. IMEI, ICCID and claim matching require AT&T records.</p><div className=\"linecards\">{lines.filter(l=>l"'!=='"'Account'&&(line==='All'||line===l)).map(l=>{let rs=allRows.filter((r:any)=>r.line===l);return <article className={l==='817-879-6788'?'flag':''} key={l}><Tablet size={24}/><h3>{l}</h3><span className=\"badge unresolved\">{l==='817-879-6788'?'Questioned tablet':l==='682-359-3466'?'Existing tablet':D.rows.find((r:any)=>r.line===l)?.device}</span><p>Selected ledger total <strong>{money(sum(rs))}</strong> <span className=\"badge calculated\">Calculation</span></p><details><summary>{rs.length} matching entries · subscriber and charge history</summary>{D.bills.flatMap((b:any)=>b.lines.filter((x:any)=>x.number===l&&(m==='All'||m===b.id)).map((x:any)=><p key={b.id}>{month(b.id)} · {x.user} · {x.device} · printed total {money(x.total)} {cite(b.id,x.page)}</p>))}{table(rs)}</details></article>})}</div></>}
{tab==='Insurance & deductibles'&&<><div className=\"metrics\"><div><small>Two printed replacement deductibles</small><strong>"'$550.00</strong><span>Legitimacy user-reported; device matching unresolved</span>{references(deduct)}</div><div><small>Separate device non-return fee</small><strong>$285.00</strong>{references(nonreturn)}</div><div><small>Third disputed deductible</small><strong>Unresolved</strong><span>User-reported · amount and statement entry unidentified</span></div></div><p className="muted">Insurance premiums, replacement deductibles and device non-return fees are separate ledger categories. The two legitimate replacements are not counted as disputed refund exposure.</p>{table(allRows.filter((r:any)=>['"'Insurance premium','Replacement deductible','Device non-return fee'].includes(r.category)))}</>}
{(tab==='Disputed items'||tab==='Unresolved questions')&&<><h2>Questions requiring account and claim records</h2><p className=\"muted\">The statements establish billing entries, not authorization, return status, entitlement to a refund or wrongdoing.</p>{D.reports.map((r:any)=><div className=\"report\" key={r.name}><span className=\"badge reported\">User-reported · Oct 5 conversation</span><h3>{r.name}</h3><p>{r.detail}</p></div>)}{questions.map(a=><article className=\"issue\" key={a.id}><div className=\"sectionheading\"><h3>{a.title}</h3><strong>{a.exposure}</strong></div><p>{a.question}</p><details><summary>Evidence and limitations</summary><p>{a.detail}</p>{references(a.refs)}</details><button onClick={()=>setTab('AT&T Store Visit')}>Record AT&T’s answer</button></article>)}</>}
{tab==='Evidence library'&&<><h2>Original statements and source register</h2><p className=\"muted\">Original PDFs are preserved. Identical September statement copies are counted once. Citations use the printed bill page, which matches the PDF page for these files; extra trailing blank pages remain in the originals. Comparison screenshots carry AT&T’s AI-content warning and are not substituted for the bills. The unrelated biography is excluded.</p>{bills.map((b:any)=><article className=\"source\" key={b.id}><div><h3>{b.date} statement</h3><small>{b.file}</small>{b.duplicates.length>0&&<small>Duplicate copies: {b.duplicates.join('; ')}</small>}</div><button onClick={()=>setEvidence({bill:b.id,page:1})}>Read original</button><a href={'/bills/'+b.id+'.pdf'} target=\"_blank\" rel=\"noreferrer\">Open PDF</a></article>)}{D.supplements.map((s:any)=><article className=\"source\" key={s.id}><div><h3>AT&T comparison screenshot</h3><small>{s.file}</small><span className=\"badge unresolved\">AI-generated comparison · not a bill</span></div><a href={'/bills/'+s.id+'.pdf'} target=\"_blank\" rel=\"noreferrer\">Open source</a></article>)}<details><summary>Extraction and reconciliation method</summary><p>Every numbered charge is stored with its exact printed amount and wording. Normalized categories are navigation aids. All 11 service totals reconcile to the signed sum of itemized service charges; payments and balance adjustments are excluded from that service calculation. Source PDFs remain authoritative. Bills are grouped by issue month, not screenshot upload time.</p></details></>}
<footer>GrizzlyMedicine Research Institute · Evidence-based account review · Prepared from supplied records as of October 5, 2026</footer></main>{evidence&&(()=>{let b=D.bills.find((x:any)=>x.id===evidence.bill);return <div className=\"modal\" role=\"dialog\" aria-modal=\"true\" aria-label=\"Statement evidence\"><div className=\"evidence\"><div className=\"evidencehead\"><div><h2>{b.date} · bill page {evidence.page}</h2><small>{b.file}</small></div><button autoFocus onClick={()=>setEvidence(null)} aria-label=\"Close evidence\"><X/></button></div><div className=\"evidenceactions\"><a href={'/bills/'+b.id+'.pdf#page='+evidence.page} target=\"_blank\" rel=\"noreferrer\">Open original PDF at page {evidence.page}</a><select value={evidence.page} onChange={e=>setEvidence({...evidence,page:+e.target.value})}>{b.pages.map((_:any,i:number)=><option key={i} value={i+1}>Page {i+1}</option>)}</select></div><div className=\"evidencebody\"><img src={'/bill-pages/'+b.id+'-'+evidence.page+'.png'} alt={"'`${b.date} original bill page ${evidence.page}`}/><details><summary>Extracted page text</summary><pre>{b.pages[evidence.page-1]||'"'No extractable text on this page.'}</pre></details></div></div></div>})()}</div>}
EOF
