account='287361795764'
def redact(t):
 for n in nums:
  tail=n[-4:]
  for v in [n,n.replace('-','.'),n.replace('-','')]:t=t.replace(v,'***.***.'+tail)
 t=t.replace(account,'********5764').replace('67053117','[redacted]')
 for v in ['8128 FOXFIRE LN APT D','WHITE SETTLEMENT, TX 76108-1178'] :t=t.replace(v,'[address removed]')
