 t=re.sub(r'\\b\\d{24,}\\b','[machine-readable identifier removed]',t)
 return t
# Mask line values consistently while preserving signed cents and source pagination.
def walk(x):
 if isinstance(x,str):return redact(x)
 if isinstance(x,list):return [walk(a) for a in x]
 if isinstance(x,dict):return {k:walk(v) for k,v in x.items()}
 return x
