 doc=fitz.open(stream=base64.b64decode(b64),filetype='pdf')
 for i,page in enumerate(doc):
  # Header addresses and names; invoice/account identifiers and all phone numbers.
  lines=page.get_text('dict')['blocks']
  for block in lines:
   if block.get('type')"'!=0:continue
   for li in block['"'lines']:
