     text=span['text'];box=fitz.Rect(span['bbox'])
     if any(v in text for v in ['8128 FOXFIRE','WHITE SETTLEMENT','JEFF HANSON','ROBERT HANSON',account,'67053117']) or re.search(r'\\b\\d{3}[.-]\\d{3}[.-]\\d{4}\\b|\\d{24,}',text):
      page.add_redact_annot(box+(-1,-1,1,1),fill=(.16,.17,.16))
  # Payment stub, bank enrollment/signature section, barcodes and embedded QR images.
  for marker in ['Return this portion','AutoPay enrollment']:
   for box in page.search_for(marker):page.add_redact_annot(fitz.Rect(0,box.y0-4,page.rect.width,page.rect.height),fill=(.96,.95,.92))
  for info in page.get_images(full=True):
   for box in page.get_image_rects(info[0]):
    if box.y0>page.rect.height*.70 or (box.width<110 and box.height<110 and box.y0>100):page.add_redact_annot(box,fill=(.96,.95,.92))
  page.apply_redactions()
  if not key.startswith('supp'):
   page.get_pixmap(matrix=fitz.Matrix(1.3,1.3)).save(root/'public/bill-pages'/f'{key}-{i+1}.png')
